{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "mdbase.app-settings 1.0.0 record contract view",
  "description": "The reserved fields every app settings record shares. Everything else in the record belongs to the app and is described by the app's own settings contract.",
  "type": "object",
  "required": ["app", "scope", "settings_version"],
  "properties": {
    "app": {
      "type": "string",
      "pattern": "^[a-z0-9]+([.-][a-z0-9]+)*$",
      "description": "The app whose clients honour these settings, such as tasknotes or dev.mdbase.reader."
    },
    "scope": {
      "enum": ["collection", "user"],
      "description": "Who the values apply to: everyone using the app in this collection, or one person."
    },
    "user": {
      "type": "string",
      "minLength": 1,
      "description": "A link to the mdbase.person record the values apply to. Present only when scope is user."
    },
    "settings_version": {
      "type": "integer",
      "minimum": 1,
      "description": "The version of the app's settings schema that last wrote the record. A client that does not understand it treats the settings as read-only."
    }
  },
  "allOf": [
    {
      "if": { "properties": { "scope": { "const": "user" } }, "required": ["scope"] },
      "then": { "required": ["user"] },
      "else": { "not": { "required": ["user"] } }
    }
  ],
  "additionalProperties": true
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "dev.mdbase.reader.settings 1.1.0",
  "description": "Collection-wide settings that every mdbase Reader client honours. Every field is optional and has a default, so a record with none of them behaves like no record at all.",
  "type": "object",
  "required": ["app", "scope", "settings_version"],
  "properties": {
    "app": {
      "const": "dev.mdbase.reader",
      "description": "Marks this record as mdbase Reader's settings."
    },
    "scope": {
      "const": "collection",
      "description": "These settings apply to everyone using Reader in this collection."
    },
    "settings_version": {
      "type": "integer",
      "minimum": 1,
      "description": "The version of these settings that last wrote the record. Reader 1 writes 1."
    },
    "source_name_template": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "default": "{{ title | slug }}",
      "description": "A Knap template for the file name of a new source note, chapters included, without .md. A / starts a folder under sources/. Only new sources use it; existing files are never renamed."
    },
    "annotation_name_template": {
      "type": "string",
      "minLength": 1,
      "maxLength": 500,
      "default": "{{ id }}",
      "description": "A Knap template for the file name of a new annotation under annotations/, without .md. Only new annotations use it; existing files are never renamed."
    },
    "highlight_colors": {
      "type": "array",
      "items": { "enum": ["yellow", "green", "blue", "pink", "purple"] },
      "minItems": 1,
      "uniqueItems": true,
      "default": ["yellow", "green", "blue", "pink", "purple"],
      "description": "The highlight colours Reader offers for new highlights and for recolouring, in order. A colour left out still draws in its colour, shows in filters and can be recoloured; Reader only stops offering it."
    },
    "highlight_meanings": {
      "type": "object",
      "properties": {
        "yellow": { "type": "string", "minLength": 1, "maxLength": 40 },
        "green": { "type": "string", "minLength": 1, "maxLength": 40 },
        "blue": { "type": "string", "minLength": 1, "maxLength": 40 },
        "pink": { "type": "string", "minLength": 1, "maxLength": 40 },
        "purple": { "type": "string", "minLength": 1, "maxLength": 40 }
      },
      "additionalProperties": false,
      "default": {},
      "description": "What each highlight colour means in this collection, such as Question for pink. Highlights store only their colour, so changing a colour's meaning relabels every highlight already in that colour."
    }
  },
  "additionalProperties": true
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://mdbase.dev/schemas/v0.3/view.schema.json",
  "title": "mdbase.view 1.0.0 record contract view",
  "description": "The contract view of a saved-view record. A type implements mdbase.view by mapping these fields; the optional type property only lets the canonical view type validate its own membership value.",
  "type": "object",
  "required": ["id", "version", "name", "views"],
  "properties": {
    "type": { "type": "string", "minLength": 1 },
    "id": { "$ref": "#/$defs/identifier" },
    "version": { "type": "integer", "minimum": 1 },
    "name": { "type": "string", "minLength": 1 },
    "description": { "type": "string" },
    "query": { "$ref": "#/$defs/sharedQuery" },
    "properties": { "$ref": "#/$defs/propertyMetadataSet" },
    "summary_functions": { "$ref": "#/$defs/summaryFunctionSet" },
    "views": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/view" }
    }
  },
  "patternProperties": {
    "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
  },
  "additionalProperties": false,
  "$defs": {
    "identifier": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9._:-]*$"
    },
    "typeName": {
      "type": "string",
      "pattern": "^[A-Za-z][A-Za-z0-9_-]{0,127}$"
    },
    "fieldName": {
      "type": "string",
      "pattern": "^[A-Za-z_][A-Za-z0-9_:-]*$"
    },
    "expression": {
      "type": "string",
      "minLength": 1
    },
    "extension": {
      "type": "object",
      "additionalProperties": true
    },
    "typeList": {
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": { "$ref": "#/$defs/typeName" }
    },
    "sharedQuery": {
      "type": "object",
      "properties": {
        "types": { "$ref": "#/$defs/typeList" },
        "where": { "$ref": "#/$defs/expression" },
        "context": { "$ref": "#/$defs/viewContext" },
        "projections": { "$ref": "#/$defs/projectionSet" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "viewContext": {
      "type": "object",
      "required": ["this"],
      "properties": {
        "this": { "$ref": "#/$defs/thisContext" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "thisContext": {
      "type": "object",
      "properties": {
        "on_missing": {
          "enum": ["view", "null", "error"],
          "default": "view"
        },
        "types": { "$ref": "#/$defs/typeList" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "projectionSet": {
      "type": "object",
      "propertyNames": { "$ref": "#/$defs/fieldName" },
      "additionalProperties": { "$ref": "#/$defs/projection" }
    },
    "projection": {
      "type": "object",
      "required": ["expr"],
      "properties": {
        "expr": { "$ref": "#/$defs/expression" },
        "description": { "type": "string" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "propertyMetadataSet": {
      "type": "object",
      "propertyNames": { "type": "string", "minLength": 1 },
      "additionalProperties": { "$ref": "#/$defs/propertyMetadata" }
    },
    "propertyMetadata": {
      "type": "object",
      "properties": {
        "label": { "type": "string" },
        "description": { "type": "string" },
        "format": { "type": "string" },
        "hidden": { "type": "boolean" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "summaryFunctionSet": {
      "type": "object",
      "propertyNames": { "$ref": "#/$defs/fieldName" },
      "additionalProperties": { "$ref": "#/$defs/summaryFunction" }
    },
    "summaryFunction": {
      "type": "object",
      "required": ["expr"],
      "properties": {
        "expr": { "$ref": "#/$defs/expression" },
        "description": { "type": "string" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "view": {
      "type": "object",
      "required": ["id", "name"],
      "properties": {
        "id": { "$ref": "#/$defs/identifier" },
        "name": { "type": "string", "minLength": 1 },
        "description": { "type": "string" },
        "types": { "$ref": "#/$defs/typeList" },
        "where": { "$ref": "#/$defs/expression" },
        "context": { "$ref": "#/$defs/viewContext" },
        "projections": { "$ref": "#/$defs/projectionSet" },
        "select": { "$ref": "#/$defs/select" },
        "order_by": { "$ref": "#/$defs/orderBy" },
        "group_by": { "$ref": "#/$defs/groupBy" },
        "summaries": { "$ref": "#/$defs/summaries" },
        "limit": { "type": "integer", "minimum": 0 },
        "offset": { "type": "integer", "minimum": 0 },
        "include_body": { "type": "boolean", "default": false },
        "frontmatter_mode": {
          "enum": ["effective", "persisted", "both"],
          "default": "effective"
        },
        "presentation": { "$ref": "#/$defs/presentation" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "select": {
      "type": "array",
      "minItems": 1,
      "items": {
        "oneOf": [
          { "type": "string", "minLength": 1 },
          { "$ref": "#/$defs/selectExpression" }
        ]
      }
    },
    "selectExpression": {
      "type": "object",
      "required": ["name", "expr"],
      "properties": {
        "name": { "$ref": "#/$defs/fieldName" },
        "expr": { "$ref": "#/$defs/expression" },
        "label": { "type": "string" },
        "description": { "type": "string" }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    },
    "orderBy": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["field"],
        "properties": {
          "field": { "type": "string", "minLength": 1 },
          "direction": { "enum": ["asc", "desc"], "default": "asc" }
        },
        "additionalProperties": false
      }
    },
    "groupBy": {
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "required": ["field"],
        "properties": {
          "field": { "type": "string", "minLength": 1 },
          "direction": { "enum": ["asc", "desc"], "default": "asc" }
        },
        "additionalProperties": false
      }
    },
    "summaries": {
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/$defs/summary" }
    },
    "summary": {
      "type": "object",
      "required": ["field", "function"],
      "properties": {
        "field": { "type": "string", "minLength": 1 },
        "function": { "$ref": "#/$defs/identifier" },
        "name": { "$ref": "#/$defs/fieldName" },
        "label": { "type": "string" }
      },
      "additionalProperties": false
    },
    "presentation": {
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": { "$ref": "#/$defs/identifier" },
        "fallback": { "$ref": "#/$defs/identifier" },
        "mappings": {
          "type": "object",
          "propertyNames": { "$ref": "#/$defs/fieldName" },
          "additionalProperties": { "type": "string", "minLength": 1 }
        },
        "options": {
          "type": "object",
          "additionalProperties": true
        }
      },
      "patternProperties": {
        "^x-[A-Za-z][A-Za-z0-9._:-]{0,127}$": { "$ref": "#/$defs/extension" }
      },
      "additionalProperties": false
    }
  }
}
